installer-gui-script.script:
function gelb_check() {
  if (system.compareVersions(system.version.ProductVersion, '@TARGET_MIN@') < 0) {
    my.result.title = 'macOS @TARGET_MIN@ or newer is required';
    my.result.message = 'This build of GeLB needs macOS @TARGET_MIN@ or newer on Apple Silicon.';
    my.result.type = 'Fatal';
    return false;
  }
  if (!system.files.fileExistsAtPath('/Applications/Xcode.app') &&
      !system.files.fileExistsAtPath('/Library/Developer/CommandLineTools/usr/bin/clang++')) {
    my.result.title = 'No C++ compiler found';
    my.result.message = 'GeLB compiles simulations with the clang++ that comes with Xcode or the Command Line Tools (xcode-select --install). You can continue; the compile check at the end of the installation will fail until one of them is installed.';
    my.result.type = 'Warning';
    return false;
  }
  return true;
}
function login_shell_is(name) {
  return system.env.SHELL != undefined && system.env.SHELL.indexOf(name) != -1;
}
